function inferAgeFromSchoolYear(year){const s=normalizeForSearch(year);let m=s.match(/([1-6])\s*o?\s*de\s*primaria/);if(m)return 5+Number(m[1]);m=s.match(/([1-4])\s*o?\s*de\s*eso/);if(m)return 11+Number(m[1]);m=s.match(/([1-2])\s*o?\s*de\s*bachillerato/);if(m)return 15+Number(m[1]);m=s.match(/infantil[^0-9]*([345])/);if(m)return Number(m[1]);return null}
function learnerAge(ctx){const direct=Number(ctx?.base?.edad);if(Number.isFinite(direct)&&direct>0)return direct;return inferAgeFromSchoolYear(ctx?.profile?.school_year)}
function ageTeachingProfile(ctx){const age=learnerAge(ctx),stage=normalizeForSearch(ctx?.profile?.stage),year=normalizeForSearch(ctx?.profile?.school_year);if(stage.includes("bachillerato")||year.includes("bachillerato")||age>=17)return{...AGE_PEDAGOGY.bach,age:age||17};if(age>=15)return{...AGE_PEDAGOGY.upper_secondary,age};if(age>=12)return{...AGE_PEDAGOGY.early_secondary,age};if(age>=9)return{...AGE_PEDAGOGY.upper_primary,age};if(age>=6)return{...AGE_PEDAGOGY.early,age};return{...AGE_PEDAGOGY.foundation,age:age||null}}
