function usageDate(env,date=new Date()){const tz=String(env.USAGE_TIMEZONE||"Europe/Madrid").trim()||"Europe/Madrid";try{const parts=new Intl.DateTimeFormat("en-US",{timeZone:tz,year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(date),map=Object.fromEntries(parts.filter(p=>p.type!=="literal").map(p=>[p.type,p.value]));return `${map.year}-${map.month}-${map.day}`}catch(e){return date.toISOString().slice(0,10)}}
function addUsageDays(dateString,days){const d=new Date(String(dateString)+"T12:00:00Z");d.setUTCDate(d.getUTCDate()+Number(days||0));return d.toISOString().slice(0,10)}
function usageWeekWindow(env,date=new Date()){const today=usageDate(env,date),d=new Date(today+"T12:00:00Z"),mondayIndex=(d.getUTCDay()+6)%7,start=addUsageDays(today,-mondayIndex),end=addUsageDays(start,6),next=addUsageDays(start,7);return{today,start,end,next}}
