async function getWeekUsage(env,uid){const w=usageWeekWindow(env);try{const rows=await supabase(env,`eterna_usage?user_id=eq.${encodeURIComponent(uid)}&usage_date=gte.${w.start}&usage_date=lte.${w.end}&select=usage_date,chat_requests`),used=(rows||[]).reduce((sum,r)=>sum+Number(r.chat_requests||0),0);return{...w,used,rows:rows||[]}}catch(e){return{...w,used:0,rows:[]}}}
async function quota(env,uid,email){
  const [settings,usage,week]=await Promise.all([getParentSettings(env,uid),getTodayUsage(env,uid),getWeekUsage(env,uid)]);
  const parentDaily=Math.max(1,Math.min(100,Number(settings.max_sessions_per_day||20))),
        hardDaily=Math.max(1,Math.min(100,Number(env.MAX_CHAT_REQUESTS_PER_DAY||60))),
        dailyLimit=Math.min(parentDaily,hardDaily),
        dailyUsed=Number(usage.chat_requests||0),
        configuredWeekly=Number(env.MAX_CHAT_REQUESTS_PER_WEEK||0),
        derivedWeekly=Math.max(7,dailyLimit*7),
        weeklyLimit=configuredWeekly>0?Math.max(7,Math.min(1000,configuredWeekly)):derivedWeekly,
        weeklyUsed=Number(week.used||0);
  if(isTesterEmail(env,email))return{ok:true,period:null,limit:dailyLimit,used:dailyUsed,daily_limit:dailyLimit,daily_used:dailyUsed,weekly_limit:weeklyLimit,weekly_used:weeklyUsed,settings,usage,week,tester:true};
  if(dailyUsed>=dailyLimit)return{ok:false,period:"daily",limit:dailyLimit,used:dailyUsed,daily_limit:dailyLimit,daily_used:dailyUsed,weekly_limit:weeklyLimit,weekly_used:weeklyUsed,settings,usage,week,tester:false};
  if(weeklyUsed>=weeklyLimit)return{ok:false,period:"weekly",limit:weeklyLimit,used:weeklyUsed,daily_limit:dailyLimit,daily_used:dailyUsed,weekly_limit:weeklyLimit,weekly_used:weeklyUsed,settings,usage,week,tester:false};
  return{ok:true,period:null,limit:dailyLimit,used:dailyUsed,daily_limit:dailyLimit,daily_used:dailyUsed,weekly_limit:weeklyLimit,weekly_used:weeklyUsed,settings,usage,week,tester:false}
}
async function markChatRequest(env,uid,q,image){try{const body={...q.usage,user_id:uid,usage_date:usageDate(env),chat_requests:Number(q.usage?.chat_requests||0)+1,image_requests:Number(q.usage?.image_requests||0)+(image?1:0),updated_at:new Date().toISOString()};await supabase(env,"eterna_usage?on_conflict=user_id,usage_date",{method:"POST",body,headers:{Prefer:"resolution=merge-duplicates,return=representation"}})}catch(e){}}
async function resendEmail(env,{to,subject,html}){const key=String(env.RESEND_API_KEY||"").trim(),from=String(env.ETERNA_ALERT_FROM_EMAIL||"").trim();if(!key||!from||!to)return{ok:false,configured:false};try{const r=await fetch("https://api.resend.com/emails",{method:"POST",headers:{Authorization:"Bearer "+key,"Content-Type":"application/json"},body:JSON.stringify({from,to:[to],subject,html})});if(!r.ok){console.error("ETERNA WEEKLY EMAIL",r.status,(await r.text()).slice(0,400));return{ok:false,configured:true}}return{ok:true,configured:true}}catch(e){console.error("ETERNA WEEKLY EMAIL NETWORK",String(e?.message||e));return{ok:false,configured:true}}}
async function weeklyNotificationExists(env,uid,periodKey){try{const rows=await supabase(env,`eterna_limit_notifications?user_id=eq.${encodeURIComponent(uid)}&period_type=eq.weekly&period_key=eq.${encodeURIComponent(periodKey)}&notification_type=eq.limit_reached&select=sent_at&limit=1`);return Boolean(rows&&rows.length)}catch(e){return false}}
async function markWeeklyNotification(env,uid,periodKey,email){try{await supabase(env,"eterna_limit_notifications?on_conflict=user_id,period_type,period_key,notification_type",{method:"POST",body:{user_id:uid,period_type:"weekly",period_key:periodKey,notification_type:"limit_reached",recipient_email_hash:email?await sha256(String(email).toLowerCase()):null,sent_at:new Date().toISOString()},headers:{Prefer:"resolution=merge-duplicates,return=representation"}})}catch(e){}}
async function notifyWeeklyLimitOnce(env,auth,q){const email=String(auth?.user?.email||"").trim(),periodKey=q?.week?.start||usageDate(env);if(!email||await weeklyNotificationExists(env,auth.user.id,periodKey))return;const site=String(env.PUBLIC_SITE_URL||"https://www.cocoenforma.com").replace(/\/+$/,"");const subject="Eterna · límite semanal alcanzado",html=`<!doctype html><html><body style="margin:0;background:#f3f8fb;font-family:Arial,sans-serif;color:#173f59"><div style="max-width:620px;margin:28px auto;background:#fff;border-radius:18px;padding:28px"><div style="font-size:12px;font-weight:700;color:#2a88ad">COCO EN FORMA · ETERNA</div><h1 style="font-size:25px;margin:10px 0 12px">Se ha alcanzado el límite semanal de Eterna</h1><p style="line-height:1.55">La cuenta ha alcanzado el límite semanal de consultas de Eterna.</p><p style="line-height:1.55">Puedes revisar el uso y los controles familiares desde Zona Familiar. El progreso escolar se mantiene guardado.</p><p style="line-height:1.55"><strong>Renovación automática:</strong> ${q?.week?.next||"al comenzar la próxima semana"}.</p><p style="margin:24px 0"><a href="${site}/" style="display:inline-block;background:#173f59;color:#fff;text-decoration:none;padding:12px 16px;border-radius:10px;font-weight:700">Abrir Coco en Forma</a></p><p style="font-size:12px;color:#718793;line-height:1.5">Este aviso no incluye preguntas, fotografías ni contenido de las conversaciones del menor.</p></div></body></html>`;const sent=await resendEmail(env,{to:email,subject,html});if(sent.ok)await markWeeklyNotification(env,auth.user.id,periodKey,email)}
async function moderate(env,text,image){const input=[];if(text)input.push({type:"text",text:String(text).slice(0,5000)});if(image)input.push({type:"image_url",image_url:{url:image}});if(!input.length)return{flagged:false};try{const r=await openai(env,"/moderations",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:"omni-moderation-latest",input})});const d=await r.json();return d.results?.[0]||{flagged:false}}catch(e){console.error("ETERNA MODERATION",String(e?.message||e));return{flagged:false,moderation_error:true}}}

