function personalDangerSignal(text){
  const s=normalizeDetectionText(text);if(!s)return false;
  return /\b(me quiero morir|quiero suicidarme|voy a suicidarme|quiero matarme|voy a matarme|quiero hacerme dano|voy a hacerme dano|me estoy haciendo dano|me autolesiono|me estan pegando|me pega(?:n)?|me obliga(?:n)? a|me amenaza(?:n)?|estoy en peligro|han abusado de mi|abusan de mi|me han violado|me explotan)\b/.test(s)
}
function unsafeOperationalIntent(text){
  const s=normalizeDetectionText(text);if(!s)return false;
  const harmful="(?:drogas?|cocaina|heroina|metanfetamina|fentanilo|crack|mdma|lsd|armas?|explosivos?|bombas?)";
  if(/\b(como|dime como|explica como|quiero|necesito|formas? de|metodos? de|pasos para|instrucciones para)\b.{0,55}\b(suicidarme|suicidarse|matarme|matarse|autolesionarme|autolesionarse|hacerme dano|hacerse dano)\b/.test(s))return true;
  if(/\b(metodos?|formas?|maneras?)\b.{0,35}\b(suicidio|autolesion|autolesiones)\b/.test(s))return true;
  if(/\b(como|dime como|quiero|necesito|pasos para|instrucciones para)\b.{0,45}\b(matar|herir|hacer dano|abusar|violar|secuestrar|envenenar)\b/.test(s))return true;
  if(/\b(como|dime como|pasos para|instrucciones para|quiero|necesito)\b.{0,55}\b(fabricar|hacer|construir|montar)\b.{0,35}\b(bomba|explosivo|arma|veneno|droga|metanfetamina|cocaina|heroina)\b/.test(s))return true;
  if(new RegExp("\\b(compr(?:ar|o|as|a|amos|an)|cons(?:eguir|igo|igues|igue|eguimos|iguen)|vend(?:er|o|es|e|emos|en)|ocult(?:ar|o|as|a|amos|an)|escond(?:er|o|es|e|emos|en)|trafic(?:ar|o|as|a|amos|an))\\b.{0,45}\\b"+harmful+"\\b").test(s))return true;
  if(new RegExp("\\b(donde|como|quiero|necesito|puedo)\\b.{0,45}\\b(compr(?:ar|o)|cons(?:eguir|igo)|ocult(?:ar|o)|escond(?:er|o)|vend(?:er|o)|trafic(?:ar|o))\\b.{0,45}\\b"+harmful+"\\b").test(s))return true;
  if(new RegExp("\\b"+harmful+"\\b.{0,55}\\b(donde|como)\\b.{0,35}\\b(compr(?:ar|o)|cons(?:eguir|igo)|ocult(?:ar|o)|escond(?:er|o)|vend(?:er|o)|trafic(?:ar|o))\\b").test(s))return true;
  if(/\b(robar|robado|robe|robé|atracar|hackear|estafar)\b/.test(s)&&/\b(como|pasos|instrucciones|quiero|necesito|sin que|ocultar|esconder|evitar que)\b/.test(s))return true;
  if(/\b(como tener sexo|quiero tener sexo|como masturbarme|pornografia|porno)\b/.test(s))return true;
  return false
}
function hardUnsafeIntent(text){return personalDangerSignal(text)||unsafeOperationalIntent(text)}
function educationalIntentSignal(text){
  const s=stripTurnPunctuation(text);if(!s)return false;
  if(/^(que|qué|como|cómo|por que|por qué|para que|para qué|cuando|cuándo|donde|dónde|quien|quién)\b/.test(s))return true;
  if(/\b(explica(?:me)?|ensena(?:me)?|define|definicion|significa|sirve|funcion(?:a|an|es)?|causas?|consecuencias?|diferencia|compara|analiza|historia de|quiero saber|quiero entender|como funciona|como ocurre|como se produce|para clase|para el colegio|para un examen|para mi examen|tema de|asignatura|concepto|literario|literatura|historico|histórico|biologia|biología|ciencias?|filosofia|filosofía)\b/.test(s))return true;
  return false
}
function academicDomainSignal(text,decision,pedState,history){
  const s=stripTurnPunctuation(text),d=decision||{};
  if(!s)return false;
  if(hasAcademicConversationContext(pedState,history)&&isShortContextualContinuation(s))return true;
  if(typeof d.subject==="string"&&d.subject.trim()&&d.intent!=="non_academic")return true;
  if(typeof d.domain==="string"&&d.domain.trim()&&!/^(personal|social|shopping|entertainment|non_academic)$/i.test(d.domain))return true;
  /* Familias léxicas de disciplinas y conceptos curriculares generales.
     No decide Safety por palabras sensibles: solo responde «¿esto parece conocimiento escolar?». */
  if(/\b(?:matematic\w*|algebr\w*|geometr\w*|fraccion\w*|porcent\w*|ecuacion\w*|raiz(?:\s+cuadrada)?|lengu\w*|literat\w*|gramat\w*|metafor\w*|sujeto|predicado|ingles|frances|idiom\w*|cienci\w*|biolog\w*|anatom\w*|salud|celul\w*|sangre|reproduccion\w*|fecundacion\w*|menstruacion\w*|pubertad|virus|vih|fisic\w*|gravedad|orbit\w*|densidad|flot\w*|quimic\w*|atom\w*|molecul\w*|geolog\w*|histori\w*|edad\s+media|feudal\w*|holocaust\w*|nazis\w*|hiroshima|nagasaki|guerr\w*|geograf\w*|filosof\w*|tecnolog\w*|arte|music\w*|educacion\s+fisica|religion\w*|politic\w*|fotosintesis|ecosistem\w*|planet\w*|luna|tierra|embaraz\w*|drog\w*|tabaco|alcohol|cancer|depresion\w*|terroris\w*|barc\w*)\b/.test(s))return true;
  if(/\b(?:en una obra|en un texto|en literatura|historicamente|históricamente|desde el punto de vista|efectos? en el cuerpo|efectos? en el cerebro|como funciona|como ocurre|por que ocurre|causas? de|consecuencias? de|para que sirve|para qué sirve|que funcion|qué función)\b/.test(s))return true;
  if(/\b(?:como|cómo)\s+nacen\s+(?:los\s+)?(?:ninos|niños|bebes|bebés)\b/.test(s))return true;
  return false
}
function clearSafetySignal(text){return hardUnsafeIntent(text)}
function clearTopicSwitchSignal(text){return unsafeOperationalIntent(text)}
function scopeV3Guard(text,decision,pedState,history){
  const d={...(decision||{})},hard=hardUnsafeIntent(text),educational=educationalIntentSignal(text),academic=academicDomainSignal(text,d,pedState,history),hasContext=hasAcademicConversationContext(pedState,history);
  if(hard)return{...d,scope:"safety",intent:personalDangerSignal(text)?"personal_risk":"operational_unsafe",request_type:personalDangerSignal(text)?"personal_help":"operation",unsafe_action:true,reason:"intención operativa peligrosa o riesgo personal explícito"};
  /* V3.1: una petición claramente académica deja de depender del azar del clasificador. Safety solo permanece si hay intención operativa/riesgo real, ya descartados arriba. */
  if(educational&&academic)return{...d,scope:"school",intent:["educational_practice","educational_analysis"].includes(d.intent)?d.intent:"educational_explanation",unsafe_action:false,reason:"intención educativa + dominio académico sin acción peligrosa; Safety operativo ya fue evaluado determinísticamente"};
  if(d.scope==="safety"&&hasContext&&isShortContextualContinuation(text))return{...d,scope:"school",intent:"educational_explanation",request_type:"continuation",unsafe_action:false,reason:"continuación neutral de un contexto escolar activo"};
  return d
}
function hasAcademicConversationContext(pedState,history){return Boolean(pedState?.active_subject||pedState?.active_concept||pedState?.active_topic||latestAssistantText(history))}
function stripTurnPunctuation(text){return normalizeDetectionText(text).trim().replace(/^[¿¡]+|[.!?¿¡]+$/g,"").trim()}
function isYesNoToken(text){return /^(si|sí|no)$/.test(stripTurnPunctuation(text))}
function isShortContextualContinuation(text){const s=stripTurnPunctuation(text);if(!s||s.length>90)return false;if(clearSafetySignal(s)||clearTopicSwitchSignal(s))return false;if(/^(dime|si|sí|no|vale|ok|aja|ajá|continua|continúa|sigue|adelante|otra vez|mas facil|más fácil|no entendi|no entendí|no entiendo|explicame|explícame|explicamelo|explícamelo|ponme un ejemplo|otro ejemplo|por que|por qué|como|cómo|y despues|y después|que paso|qué pasó|no lo se|no lo sé)$/.test(s))return true;if(/^[a-d]$/.test(s)||/^-?\d+(?:[.,]\d+)?$/.test(s))return true;if(/^(creo que|pienso que|la respuesta es)\b/.test(s)&&s.length<=90)return true;return false}
function studentIntentFromRelation(relation){const map={new_topic:"new_topic",answer_to_pending:"answer",answer_to_offer:"continue",continuation_request:"continue",confusion_request:"confused",simplification_request:"simplify",detail_request:"detail",technical_request:"technical",why_request:"why",example_request:"example",invalid_short_answer:"invalid_short_answer",acknowledgement:"acknowledgement"};return map[relation]||"other"}
