  if(/\b(matematic|algebr|geometr|fraccion|porcent|ecuacion|raiz cuadrada|division|multiplicacion|aritmetic)\w*/.test(q))return"Matemáticas";
  if(/\b(fisic|gravedad|arquimed|densidad|flotacion|flotar|empuje|fuerza|energia|movimiento|orbita|velocidad|presion)\w*/.test(q))return primary?"Ciencias Naturales":"Física";
  if(/\b(biolog|anatom|celul|sangre|reproduccion|fecundacion|menstruacion|pubertad|vih|sida|virus|ecosistem|fotosintesis|salud)\w*/.test(q))return primary?"Ciencias Naturales":"Biología";
  if(/\b(quimic|molecul|reaccion quimica|elemento quimico|tabla periodica)\w*/.test(q))return primary?"Ciencias Naturales":"Química";
  if(/\b(histori|feudal|edad media|holocaust|nazi|hiroshima|nagasaki|guerra mundial|revolucion|imperio|prehistoria)\w*/.test(q))return primary?"Ciencias Sociales":"Historia";
  if(/\b(geograf|continente|relieve|rio|clima|poblacion|mapa)\w*/.test(q))return primary?"Ciencias Sociales":"Geografía";
