    function number(){ws();const m=source.slice(i).match(/^(?:\d+(?:\.\d*)?|\.\d+)/);if(!m)return null;i+=m[0].length;return Number(m[0])}
    function primary(){ws();if(source[i]==="+"){i++;return primary()}if(source[i]==="-"){i++;const v=primary();return v==null?null:-v}if(source[i]==="("){i++;const v=add();ws();if(source[i]!==")")return null;i++;return v}return number()}
    function mul(){let v=primary();if(v==null)return null;while(true){ws();const op=source[i];if(op!=="*"&&op!=="/")break;i++;const r=primary();if(r==null||(op==="/"&&r===0))return null;v=applyOp(v,r,op);ops++;if(!Number.isFinite(v))return null}return v}
